export function WidthDemo({
  mode = "{{mode}}",
  value = {{value}},
  align = "{{align}}",
  background = "{{background}}",
}) {
  const boxWidth = mode === "auto" ? "auto" : `${value}${mode}`;
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", width: 300 }}
      role="img" aria-label="An element's width set in pixels, percent of its container, or auto to fit content, aligned by the container's justify-content">
      <div style={{ width: 300, background: "#FAF7F2", border: "1.5px dashed #24143055", borderRadius: 8, padding: 10, boxSizing: "border-box", display: "flex", justifyContent: align }}>
        <div style={{ width: boxWidth, background, borderRadius: 6, padding: mode === "auto" ? "12px 14px" : "12px 0", textAlign: "center", fontWeight: 700 }}>
          box
        </div>
      </div>
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430cc" }}>width: {value}{mode} &middot; justify-content: {align} (container is 300px wide)</p>
    </div>
  );
}
